def join_gpxs(xmls: Iterable[AnyStr]) ->str:
    if not xmls:
        return ''

    doms = [mod_minidom.parseString(xml) for xml in xmls]
    main_dom = doms[0]
    main_gpx = _find_gpx_node(main_dom)

    for dom in doms[1:]:
        gpx = _find_gpx_node(dom)
        if gpx:
            for child in gpx.childNodes[:]:  # Use slice to avoid issues with modifying during iteration
                if child.nodeType == child.ELEMENT_NODE:
                    main_gpx.appendChild(main_dom.importNode(child, True))

    return main_dom.toxml()

def _find_gpx_node(dom: Any) ->Any:
    for node in dom.childNodes:
        if node.nodeType == node.ELEMENT_NODE and node.tagName == 'gpx':
            return node
    return None
